import AjvImport from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

interface AjvCompiler {
  compile(schema: Record<string, unknown>): ValidateFunction;
}

type AjvConstructor = new (options?: Record<string, unknown>) => AjvCompiler;

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = createAjvCompiler();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private resolveValidator(tool: StoredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const resolved = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicValidators.get(resolved.inputSchema);
    if (cached) return cached;
    const compiled = compileSchema(this.ajv, resolved);
    this.dynamicValidators.set(resolved.inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : compileSchema(this.ajv, resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input per specs/hal-engine-tool-input-validation/spec.md; throws only for unknown tools. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool);
    if (!validate(input)) {
      const rejection = formatValidationRejection(name, validate.errors);
      log.warn('tool', 'input validation failed', {name, errors: rejection.summary});
      return {result: rejection.message};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function createAjvCompiler(): AjvCompiler {
  const AjvCtor = resolveAjvConstructor(AjvImport);
  return new AjvCtor({strict: false, validateFormats: false});
}

function resolveAjvConstructor(imported: unknown): AjvConstructor {
  if (hasDefaultFunction(imported)) return imported.default;
  if (typeof imported === 'function') return imported as AjvConstructor;
  throw new Error('Unable to load Ajv constructor');
}

function hasDefaultFunction(candidate: unknown): candidate is {default: AjvConstructor} {
  if (candidate === null) return false;
  if (typeof candidate !== 'object' && typeof candidate !== 'function') return false;
  return 'default' in candidate && typeof candidate.default === 'function';
}

function compileSchema(ajv: AjvCompiler, definition: ToolDefinition): ValidateFunction {
  try {
    return ajv.compile(definition.inputSchema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${definition.name}": ${detail}`, {cause: error});
  }
}

interface ValidationRejection {
  message: string;
  summary: string[];
}

function formatValidationRejection(toolName: string, errors: ErrorObject[] | null | undefined): ValidationRejection {
  const summary = (errors ?? []).map(formatValidationError);
  const detail = summary.join('; ') || 'schema validation failed';
  return {
    message: `Invalid input for tool "${toolName}": ${detail}`,
    summary,
  };
}

function formatValidationError(validationError: ErrorObject): string {
  if (validationError.keyword === 'required') {
    const missingProperty = validationError.params.missingProperty;
    const propertyName = typeof missingProperty === 'string' ? missingProperty : '';
    return `${joinFieldPath(validationError.instancePath, propertyName)}: missing required property`;
  }
  const fieldPath = formatInstancePath(validationError.instancePath);
  return `${fieldPath}: ${validationError.message ?? validationError.keyword}`;
}

function joinFieldPath(instancePath: string, propertyName: string): string {
  const basePath = formatInstancePath(instancePath);
  if (!propertyName) return basePath;
  return basePath === 'input' ? propertyName : `${basePath}.${propertyName}`;
}

function formatInstancePath(instancePath: string): string {
  if (instancePath.length === 0) return 'input';
  return instancePath.replace(/^\//, '').replace(/\//g, '.');
}

