  validate?: AjvValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = createAjvCompiler();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, AjvValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private resolveValidator(tool: StoredTool): AjvValidateFunction {
    if (tool.validate) return tool.validate;
    const resolved = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicValidators.get(resolved.inputSchema);
    if (cached) return cached;
    const compiled = compileSchema(this.ajv, resolved);
    this.dynamicValidators.set(resolved.inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : compileSchema(this.ajv, resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input per specs/hal-engine-tool-input-validation/spec.md; throws only for unknown tools. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool);
    if (!validate(input)) {
      const rejection = formatValidationRejection(name, validate.errors);
      log.warn('tool', 'input validation failed', {name, errors: rejection.summary});
      return {result: rejection.message};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function createAjvCompiler(): AjvCompiler {
  const AjvCtor = resolveAjvConstructor(AjvImport);
  return new AjvCtor({strict: false, validateFormats: false});
}

function resolveAjvConstructor(imported: unknown): AjvConstructor {
  if (hasDefaultFunction(imported)) return imported.default;
  if (typeof imported === 'function') return imported as AjvConstructor;
  throw new Error('Unable to load Ajv constructor');
}

function hasDefaultFunction(candidate: unknown): candidate is {default: AjvConstructor} {
  if (candidate === null) return false;
  if (typeof candidate !== 'object' && typeof candidate !== 'function') return false;
  return 'default' in candidate && typeof candidate.default === 'function';
}

function compileSchema(ajv: AjvCompiler, definition: ToolDefinition): AjvValidateFunction {
  try {
    return ajv.compile(definition.inputSchema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${definition.name}": ${detail}`, {cause: error});
  }
}

interface ValidationRejection {
  message: string;
  summary: string[];
}

function formatValidationRejection(toolName: string, errors: AjvErrorObject[] | null | undefined): ValidationRejection {
  const summary = (errors ?? []).map(formatValidationError);
  const detail = summary.join('; ') || 'schema validation failed';
  return {
    message: `Invalid input for tool "${toolName}": ${detail}`,
    summary,
  };
}

function formatValidationError(validationError: AjvErrorObject): string {
  const fieldPath = formatErrorPath(validationError);
  if (validationError.keyword === 'required') {
    const propertyName = extractMissingProperty(validationError.params);
    return `${joinFieldPath(fieldPath, propertyName)}: missing required property`;
  }
  return `${fieldPath}: ${validationError.message ?? validationError.keyword}`;
}

function extractMissingProperty(errorParams: object | undefined): string {
  if (!errorParams) return '';
  if (!('missingProperty' in errorParams)) return '';
  return typeof errorParams.missingProperty === 'string' ? errorParams.missingProperty : '';
}

function joinFieldPath(basePath: string, propertyName: string): string {
  if (!propertyName) return basePath;
  return basePath === 'input' ? propertyName : `${basePath}.${propertyName}`;
}

function formatErrorPath(validationError: AjvErrorObject): string {
  const rawPath = readErrorPath(validationError);
  if (rawPath.length === 0) return 'input';
  if (rawPath.startsWith('/')) return rawPath.slice(1).replace(/\//g, '.');
  return rawPath.replace(/^\./, '');
}

function readErrorPath(validationError: AjvErrorObject): string {
  if (typeof validationError.instancePath === 'string') return validationError.instancePath;
  if (typeof validationError.dataPath === 'string') return validationError.dataPath;
  return '';
}

